%[text] # BEV System Model - Simulation Case
%[text] Using constant inputs, make sure the model loads and simulation runs.
model_name = "BEV_system_model";
load_system(model_name)
BEV_setup_Basic %[output:09c0e256]
loadLUTData_VehSpdRef_zero

sim_in = Simulink.SimulationInput(model_name);
sim_in = setBlockParameter(sim_in, ...
  model_name + "/Controller and Environment/Vehicle speed reference", ...
  ReferencedSubsystem = "VehSpdRef_LookupTable_refsub");
sim_in = setModelParameter(sim_in, StopTime = "100");
applyToModel(sim_in)
sim_out = sim(sim_in);
sim_data = extractTimetable(sim_out.logsout);
fig = BEV_plotResults(TimedData = sim_data, PlotTemperature = false); %[output:6986bc75]
